X, R, A = F.X, F.REAL, F.API
out = []


def w(s=""):
    out.append(s)


def table(header, rows):
    w("| " + " | ".join(header) + " |")
    w("|" + "|".join("---" for _ in header) + "|")
    for r in rows:
        w("| " + " | ".join(str(c) for c in r) + " |")
    w()


